mapper.select:
SELECT COUNT(DISTINCT um.id)
FROM ums_member um
WHERE um.status = 1
    AND (
        EXISTS (
            SELECT 1 FROM ums_member_login_log umll
            WHERE umll.member_id = um.id
                AND umll.create_time BETWEEN #{startDate} AND #{endDate}
        )
        OR EXISTS (
            SELECT 1 FROM oms_order oo
            WHERE oo.member_id = um.id
                AND oo.create_time BETWEEN #{startDate} AND #{endDate}
        )
    )

SELECT COUNT(*)
FROM ums_member_login_log
WHERE create_time BETWEEN #{startDate} AND #{endDate}

SELECT COUNT(DISTINCT COALESCE(member_id, ip))
FROM ums_member_login_log
WHERE create_time BETWEEN #{startDate} AND #{endDate}
